sys_script_include.script:
gs.include("IllumioConstants");
var IllumioStartAuthentication = Class.create();
IllumioStartAuthentication.prototype = {

    initialize: function () {
        this.logger = new IllumioLogger(null, 'IllumioStartAuthentication');
        this.scheduledJobsGr = new GlideRecordSecure(TABLE_SCHEDULED_JOBS);
        this.utils = new x_illu2_illumio.IllumioUtils();
    },

    /**
     * Creates a scheudle job and triggers the authentication process
     */
    process: function (configSysId) {

        // Create new job
        this.scheduledJobsGr.job_started = new GlideDateTime();
		this.scheduledJobsGr.illumio_pce_configuration = configSysId;
        this.scheduledJobsGr.job_status = JOB_STATUS_RUNNING;
		this.scheduledJobsGr.job_owner = gs.getUser().getID();
        this.scheduledJobsGr.current_operation = 'Connectivity check with PCE';
        this.scheduledJobsGr.logs = 'MID Server is running and it is up-to-date';
        this.scheduledJobsGr.logs += '\nMID Server user has required roles';
        this.scheduledJobsGr.logs += '\nStarted validating the connectivity with PCE';
        this.scheduledJobsGr.job_type = JOB_TYPE_CONNECTIVITY_CHECK;
        var jobSysId = this.scheduledJobsGr.insert();

        if (!this.startAuthetication(jobSysId,configSysId)) {
            this.utils.handleFailure(jobSysId, 'Connectivity check start error', 'Adding to ECC queue failed',configSysId);
        }
    },

    /**
     * Starts the authentication via MID server for check PCE configuration
     * @params {String} jobSysId system id of the process monitor
     * @return {boolean} Whether the process of creating ECC queue passed or not
     */
    startAuthetication: function (jobSysId,configSysId) {

        // NI8. The job row is inserted by process() just above; this is the first point inside
        // the class that holds its sys_id, and the single line below is the only one this class
        // writes. Without it, the one log line a connectivity check produces was not in the
        // connectivity check's own trail.
        this.logger.setContext(jobSysId);

        this.logger.info("Initiating a job to check PCE connectivity.");

        // F18 GUARD. This method is reached SYNCHRONOUSLY from the `Check PCE Configuration` UI
        // Action -- process() is called directly, not through gs.eventQueueScheduled -- so it runs
        // in the clicking user's transaction and the clicking user's ACLs apply. That is the whole
        // difference between this path and the preview/export/sync paths, which hand off to a
        // Script Action and execute as `system` with every privilege. The twin of this guard is in
        // IllumioStartDiscovery.createAsyncJobs, which is the only other synchronous entry point;
        // a change to one belongs in both.
        //
        // Two things inside getConfiguration() throw for a user who is not a platform admin, and
        // IllumioGetPCEConfiguration wraps neither:
        //   - `String(pceConfig.mid_server.name)` dot-walks into ecc_agent, which the GLOBAL
        //     `mid_server` role governs, not any x_illu2_illumio role;
        //   - the two getDecryptedValue() calls on username / secret_key.
        //
        // process() inserted the job at JOB_STATUS_RUNNING before calling this, and its only
        // failure handling is `if (!this.startAuthetication(...))` -- which a THROW bypasses
        // entirely. So an unguarded exception here left the job `running` until
        // x_illu2_illumio.invalidate_authentication_job_limit (3600s) force-cancelled it, and
        // because R46 makes a connectivity check hold its configuration while it runs, it blocked
        // every other job on that configuration for the hour. Measured 2026-10-05: a user holding
        // all four x_illu2_illumio roles but not the global mid_server role hung here indefinitely.
        //
        // Returning false routes into process()'s handleFailure, which is the same path a refused
        // ECC insert already takes.
        var pceConfig = null;
        try {
            pceConfig = new IllumioGetPCEConfiguration(jobSysId).getConfiguration(configSysId);
        } catch (ex) {
            this.utils.handleFailure(
                jobSysId,
                'PCE Configuration unreadable',
                'Could not read PCE Configuration ' + configSysId + '. Exception: ' + ex +
                '. If the MID Server field appears empty, the user who started this job is ' +
                'missing the global mid_server role, which governs read access to ecc_agent.',
                configSysId
            );
            return false;
        }

        // ORDERING FIX (R13 -- the original two lines are kept below, commented, not deleted).
        // `var org_id = pceConfig.pceOrganizationID;` used to sit immediately after the
        // getConfiguration() call, ABOVE the `if (pceConfig)` further down. That made the null
        // branch unreachable: when getConfiguration() returned null -- its documented "No
        // configuration found." result -- the dereference threw before the check that existed to
        // catch it ever ran, and the throw escaped process() into the same permanent `running`
        // state described above. The check now comes first; org_id is read after it.
        //
        //     var pceConfig = new IllumioGetPCEConfiguration(jobSysId).getConfiguration(configSysId);
        //     var org_id = pceConfig.pceOrganizationID;
        //
        if (!pceConfig) {
            this.utils.handleFailure(
                jobSysId,
                'PCEConfiguration',
                'Cannot find PCE configuration ' + configSysId,
                configSysId
            );
            return false;
        }

        // The same check IllumioPreviewUtils:797 already applies on the preview path, which is why
        // previews fail cleanly where this hung. An empty midServer means the ecc_agent read
        // returned nothing -- either the field is genuinely unset on the configuration, or the
        // caller cannot read it. Queueing to agent 'mid.server.' with no name produces an ECC row
        // no MID Server will ever claim, which is a hang rather than a failure.
        if (gs.nil(pceConfig.midServer)) {
            this.utils.handleFailure(
                jobSysId,
                'No MID Server',
                'PCE Configuration ' + configSysId + ' resolved no MID Server, so the ' +
                'connectivity check cannot be sent. Either the MID Server field is unset on the ' +
                'configuration, or the user who started this job cannot read it -- that read ' +
                'requires the global mid_server role.',
                configSysId
            );
            return false;
        }

        var org_id = pceConfig.pceOrganizationID;
        var label_dimension_api_endpoint = "/api/v2/orgs/"+org_id+"/label_dimensions";


        if (this.utils.isJobCancelled(jobSysId))
            return false;

        // Now always true -- the !pceConfig guard above returns before reaching this. Kept per R13
        // rather than flattened, so the else branch below stays visible as the thing that used to
        // be unreachable. It is now dead for the opposite reason: nothing can get here with a null
        // pceConfig. Collapse both in the deliberate deletion pass, not incidentally.
        if (pceConfig) {
            var parameters = {
				illumio_pce_configuration_id: configSysId,
                pce_url: pceConfig.pceUrl,
                pce_authorization: gs.base64Encode(pceConfig.pceUsername + ':' + pceConfig.pceSecret),
                pce_endpoint: label_dimension_api_endpoint,
                illumio_scheduled_job_id: jobSysId,
                time_zone: gs.getSession().getTimeZoneName(),
				enable_pce_mid_proxy: pceConfig.enable_pce_mid_proxy,
				retry_params: JSON.stringify(pceConfig.retry_params)
            };
            var illumioAddToECCQueue = new IllumioAddToECCQueue('IllumioAuthenticateToPCE', pceConfig.midServer, parameters);
            var addToECCQueue = illumioAddToECCQueue.insert();

            if (!addToECCQueue) {
                this.utils.handleFailure(jobSysId, 'Adding to ECC queue', 'Adding task for async job of fetching workloads to ECC queue failed', configSysId);
                return false;
            }
            return true;
        } else {
            this.utils.handleFailure(jobSysId, 'PCEConfiguration', 'Cannot find PCE configuration', configSysId);
            return false;
        }

    },

    type: 'IllumioStartAuthentication'
};
